mapper.select:
/* com.portal.system.code.zip.ZipManageMapper.selectZipList */ SELECT ZIP AS zip, SN AS sn, CTPRVN_NM AS ctprvnNm, SIGNGU_NM AS signguNm, EMD_NM AS emdNm, LI_BULD_NM AS liBuldNm, LNBR_DONG_HO AS lnbrDongHo FROM LETTCZIP WHERE 1 = 1
AND ZIP = #{searchKeyword}
AND CTPRVN_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND SIGNGU_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND EMD_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND LI_BULD_NM LIKE CONCAT('%', #{searchKeyword}, '%')
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.system.code.zip.ZipManageMapper.selectZipListTotCnt */ SELECT COUNT(*) AS totcnt FROM LETTCZIP WHERE 1 = 1
AND ZIP = #{searchKeyword}
AND CTPRVN_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND SIGNGU_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND EMD_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND LI_BULD_NM LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.insert:
/* com.portal.system.code.zip.ZipManageMapper.insertZip */
SELECT IFNULL(MAX(SN), 0) + 1 AS sn FROM LETTCZIP
INSERT INTO LETTCZIP ( ZIP, SN, CTPRVN_NM, SIGNGU_NM, EMD_NM, LI_BULD_NM, LNBR_DONG_HO, FRST_REGIST_PNTTM, FRST_REGISTER_ID, LAST_UPDT_PNTTM, LAST_UPDUSR_ID ) VALUES ( #{zip}, #{sn}, #{ctprvnNm}, #{signguNm}, #{emdNm}, #{liBuldNm}, #{lnbrDongHo}, SYSDATE(), #{frstRegisterId}, SYSDATE(), #{frstRegisterId} )

mapper.update:
/* com.portal.system.code.zip.ZipManageMapper.updateZip */
UPDATE LETTCZIP
   SET CTPRVN_NM       = #{ctprvnNm},
       SIGNGU_NM       = #{signguNm},
       EMD_NM          = #{emdNm},
       LI_BULD_NM      = #{liBuldNm},
       LNBR_DONG_HO    = #{lnbrDongHo},
       LAST_UPDT_PNTTM = SYSDATE(),
       LAST_UPDUSR_ID  = #{lastUpdusrId}
 WHERE ZIP = #{zip}
   AND SN  = #{sn}
